from quant_system.factors.base import BaseFactor


class PaperShortTermReversalProxy(BaseFactor):
    factor_id = "paper_short_term_reversal_proxy_v1"
    factor_name = "Paper Short-Term Reversal Proxy"
    factor_version = "0.1.0"
    default_lookback = 21
    direction = "higher_is_better"
    description = (
        "Operational 21-trading-day reversal proxy inspired by "
        "DOI 10.1093/rfs/hhaf057; not a full global paper replication."
    )

    def _compute_values(self, frame):
        trailing_return = frame.groupby("symbol", sort=False)["close"].pct_change(
            self.lookback
        )
        return -trailing_return
